import { pgTable, text, serial, timestamp } from "drizzle-orm/pg-core";
import { createInsertSchema } from "drizzle-zod";
import { z } from "zod/v4";

export const siteContentTable = pgTable("site_content", {
  id: serial("id").primaryKey(),
  heroTitle: text("hero_title").notNull().default("Rejoignez le Réseau Business le Plus Puissant d'Afrique"),
  heroSubtitle: text("hero_subtitle").notNull().default("Gagnez de l'argent par affiliation, développez votre visibilité, accédez à des formations exclusives."),
  heroCtaText: text("hero_cta_text").notNull().default("Rejoindre Maintenant"),
  memberCount: text("member_count").notNull().default("12,500+"),
  memberCountLabel: text("member_count_label").notNull().default("Membres actifs dans le réseau"),
  geoAvailability: text("geo_availability").notNull().default("Cameroun, Côte d'Ivoire, Sénégal, RDC, Mali, Gabon, Togo, Bénin, Burkina Faso, Guinée"),
  promoTitle: text("promo_title").notNull().default("Sois payé pour publier du contenu sur ton statut WhatsApp"),
  promoDescription: text("promo_description").notNull().default("Avec la nouvelle fonctionnalité de la Sniper Business Center, publie les contenus de nos partenaires sur ton statut WhatsApp et gagne de l'argent à chaque publication. Plus tu as de vues, plus tu gagnes : ton statut devient une véritable source de revenus."),
  promoVideoUrl: text("promo_video_url").notNull().default(""),
  promoPosterUrl: text("promo_poster_url").notNull().default(""),
  promoCtaText: text("promo_cta_text").notNull().default("Je m'inscris maintenant"),
  videoUrl: text("video_url").notNull().default("https://www.youtube.com/embed/dQw4w9WgXcQ"),
  presentationTitle: text("presentation_title").notNull().default("Découvrez Biz Connect Academy"),
  countriesTitle: text("countries_title").notNull().default("Disponible dans plus de 20 pays d'Afrique"),
  benefitsTitle: text("benefits_title").notNull().default("Voici ce que tu vas gagner en nous rejoignant"),
  ambassadorsTitle: text("ambassadors_title").notNull().default("Nos ambassadeurs"),
  gainsTitle: text("gains_title").notNull().default("Tes gains par affiliation"),
  gainsSecondaryTitle: text("gains_secondary_title").notNull().default("À la Biz Connect Academy, même si tu dors, ton téléphone travaille pour toi."),
  testimonialsTitle: text("testimonials_title").notNull().default("De nombreux jeunes venant de plusieurs pays se sont lancés et voilà leurs résultats et témoignages"),
  trainingsTitle: text("trainings_title").notNull().default("Catalogue de formations"),
  ctaTitle: text("cta_title").notNull().default("Tu veux commencer ?"),
  faqTitle: text("faq_title").notNull().default("Questions fréquentes"),
  supportTitle: text("support_title").notNull().default("Contacte le support"),
  partnersTitle: text("partners_title").notNull().default("Nos partenaires"),
  paymentMethodsTitle: text("payment_methods_title").notNull().default("Moyens de paiement acceptés"),
  offerPrice: text("offer_price").notNull().default("25,000 FCFA"),
  offerOriginalPrice: text("offer_original_price").notNull().default("50,000 FCFA"),
  offerLabel: text("offer_label").notNull().default("Inscriptions à vie"),
  level1Name: text("level1_name").notNull().default("Niveau Bronze"),
  level1Amount: text("level1_amount").notNull().default("2,500 FCFA"),
  level2Name: text("level2_name").notNull().default("Niveau Argent"),
  level2Amount: text("level2_amount").notNull().default("5,000 FCFA"),
  level3Name: text("level3_name").notNull().default("Niveau Or"),
  level3Amount: text("level3_amount").notNull().default("10,000 FCFA"),
  whatsappNumber: text("whatsapp_number").notNull().default("237690000000"),
  heroImageUrl: text("hero_image_url").notNull().default(""),
  signupUrl: text("signup_url").notNull().default("/inscription"),
  communityImageUrl: text("community_image_url").notNull().default(""),
  countriesIconUrl: text("countries_icon_url").notNull().default(""),
  gainsPosterUrl: text("gains_poster_url").notNull().default(""),
  gainsSecondaryImageUrl: text("gains_secondary_image_url").notNull().default(""),
  telegramLink: text("telegram_link").notNull().default(""),
  telegramChannelLink: text("telegram_channel_link").notNull().default(""),
  facebookLink: text("facebook_link").notNull().default(""),
  tiktokLink: text("tiktok_link").notNull().default(""),
  instagramLink: text("instagram_link").notNull().default(""),
  youtubeLink: text("youtube_link").notNull().default(""),
  whatsappChannelLink: text("whatsapp_channel_link").notNull().default(""),
  supportPhone1: text("support_phone1").notNull().default(""),
  supportPhone2: text("support_phone2").notNull().default(""),
  suggestionsIntroText: text("suggestions_intro_text").notNull().default("Faite nous parvenir vos suggestions, dans cette espace, vous pouvez nous faire parvenir vos suggestions afin que nous puissions résoudre efficacement certains problème que vous rencontrez et ensemble nous ferons évoluer notre communauté"),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow().$onUpdate(() => new Date()),
});

export const insertSiteContentSchema = createInsertSchema(siteContentTable).omit({ id: true, updatedAt: true });
export type InsertSiteContent = z.infer<typeof insertSiteContentSchema>;
export type SiteContent = typeof siteContentTable.$inferSelect;
